-- Follow-up to private-wealth-plan-flows.sql: collect both leads before delivery.
-- Existing API credentials remain server-side in the unchanged shared HTTP nodes.
begin;
do $offers$
declare original zernflow.flows%rowtype; plan zernflow.flows%rowtype; reply zernflow.flows%rowtype;
begin
select * into strict original from zernflow.flows where id='02b54e75-866f-4636-a357-38eb0b7a3b35' for update;
select * into strict plan from zernflow.flows where id='ecaa8b22-f1ab-4bf6-badd-d9ead44322b5' for update;
select * into strict reply from zernflow.flows where id='7edcff18-8b62-49c3-966a-65625671dc15' for update;
if original.version<>7 or plan.version<>2 or reply.version<>26 then raise exception 'Flow changed; inspect before applying'; end if;
insert into zernflow.flow_versions(flow_id,version,nodes,edges,viewport,name)
select id,version,nodes,edges,viewport,name from zernflow.flows f where id in(original.id,plan.id,reply.id)
and not exists(select 1 from zernflow.flow_versions v where v.flow_id=f.id and v.version=f.version);
update zernflow.flows set nodes=(select jsonb_agg(case when n->>'id'='msg-email' then jsonb_set(n,'{data}','{"label": "x", "messages": [{"text": "Hey sis! ❤️ I saw you commented WEALTH FLOW, I just need your email so I can send it to you!"}]}'::jsonb) when n->>'id'='wealth-plan-pending' then jsonb_set(n,'{data,label}','"Mark Wealth Flow request"') else n end order by ord) from jsonb_array_elements(original.nodes) with ordinality a(n,ord)) || '[{"id": "clear-other-offer", "type": "action", "data": {"label": "clear-other-offer", "actionType": "removeTag", "tagName": "private_wealth_plan_pending"}, "position": {"x": 650, "y": 200}}]'::jsonb, edges='[{"id": "trigger-1-msg-email", "source": "trigger-1", "target": "msg-email"}, {"id": "msg-email-clear-other-offer", "source": "msg-email", "target": "clear-other-offer"}, {"id": "clear-other-offer-wealth-plan-pending", "source": "clear-other-offer", "target": "wealth-plan-pending"}]'::jsonb,version=version+1,published_at=now(),updated_at=now() where id=original.id;
update zernflow.flows set nodes=(select jsonb_agg(n) from jsonb_array_elements(plan.nodes)n where n->>'type'='trigger') || '[{"id": "msg-private-plan", "type": "sendMessage", "data": {"label": "msg-private-plan", "messages": [{"text": "Hey sis! ❤️ I saw you commented WEALTH PLAN, I just need your email so I can send it to you!"}]}, "position": {"x": 650, "y": 200}}, {"id": "clear-other-offer", "type": "action", "data": {"label": "clear-other-offer", "actionType": "removeTag", "tagName": "wealth_plan_pending"}, "position": {"x": 650, "y": 200}}, {"id": "mark-private-plan", "type": "action", "data": {"label": "mark-private-plan", "actionType": "addTag", "tagName": "private_wealth_plan_pending"}, "position": {"x": 650, "y": 200}}]'::jsonb,edges='[{"id": "trigger-1-msg-private-plan", "source": "trigger-1", "target": "msg-private-plan"}, {"id": "msg-private-plan-clear-other-offer", "source": "msg-private-plan", "target": "clear-other-offer"}, {"id": "clear-other-offer-mark-private-plan", "source": "clear-other-offer", "target": "mark-private-plan"}]'::jsonb,description='Collect email first, then deliver a personalized Private Wealth Plan link through the shared Systeme.io reply handler.',version=version+1,published_at=now(),updated_at=now() where id=plan.id;
update zernflow.flows set nodes=(select jsonb_agg(case when n->>'id'='node_1792266611424_7' then jsonb_set(n,'{data,messages,0,text}','"Hey sis! ❤️ I saw you commented WEALTH FLOW, so here it is! This is the exact $0-$5K savings strategy I used to stop watching my checks disappear.\n\nI’m dropping the link so you can get started RIGHT NOW! 👇🏾"'::jsonb) when n->>'id'='wealth-plan-reply-check' then jsonb_set(n,'{data,label}','"Wealth Flow email reply?"') else n end order by ord) from jsonb_array_elements(reply.nodes) with ordinality a(n,ord)) || '[{"id": "offer-reply-router", "type": "condition", "data": {"label": "offer-reply-router", "logic": "and", "conditions": [{"field": "tag:private_wealth_plan_pending", "value": "true", "operator": "equals"}]}, "position": {"x": 650, "y": 150}}, {"id": "offer-delivery-router", "type": "condition", "data": {"label": "offer-delivery-router", "logic": "and", "conditions": [{"field": "tag:private_wealth_plan_pending", "value": "true", "operator": "equals"}]}, "position": {"x": 650, "y": 350}}, {"id": "register-private-plan", "type": "action", "data": {"label": "Save Wealth Plan lead and apply Leads tag", "actionType": "httpRequest", "method": "POST", "url": "https://www.thewealthywomanrecode.com/api/wealth-plan-lead", "body": "{\"email\":\"{{captured_email}}\"}", "responseVariable": "private_plan_lead"}, "position": {"x": 650, "y": 550}}, {"id": "clear-private-plan", "type": "action", "data": {"label": "clear-private-plan", "actionType": "removeTag", "tagName": "private_wealth_plan_pending"}, "position": {"x": 650, "y": 750}}, {"id": "deliver-private-plan", "type": "sendMessage", "data": {"label": "deliver-private-plan", "messages": [{"text": "Got it, your wealth plan is headed to your email! This is the exact $0-$5K savings strategy I used to stop watching my checks disappear.\n\nI’m dropping the link right here too so you can get started RIGHT NOW! 👇🏾", "buttons": [{"type": "url", "title": "BUILD MY $5K+ PLAN", "url": "{{wealth_plan_url}}"}]}]}, "position": {"x": 650, "y": 950}}]'::jsonb, edges=(select jsonb_agg(case when e->>'source'='node_1792264737118_2' then jsonb_set(e,'{target}','"offer-reply-router"') when e->>'source'='sync-systeme-social-name' then jsonb_set(e,'{target}','"offer-delivery-router"') else e end order by ord) from jsonb_array_elements(reply.edges) with ordinality a(e,ord)) || '[{"id": "offer-reply-router-wealth-plan-valid-email", "source": "offer-reply-router", "target": "wealth-plan-valid-email", "sourceHandle": "true"}, {"id": "offer-reply-router-wealth-plan-reply-check", "source": "offer-reply-router", "target": "wealth-plan-reply-check", "sourceHandle": "false"}, {"id": "offer-delivery-router-register-private-plan", "source": "offer-delivery-router", "target": "register-private-plan", "sourceHandle": "true"}, {"id": "offer-delivery-router-systeme-wealth-plan-tag", "source": "offer-delivery-router", "target": "systeme-wealth-plan-tag", "sourceHandle": "false"}, {"id": "register-private-plan-clear-private-plan", "source": "register-private-plan", "target": "clear-private-plan"}, {"id": "register-private-plan-systeme-service-retry", "source": "register-private-plan", "target": "systeme-service-retry", "sourceHandle": "error"}, {"id": "clear-private-plan-deliver-private-plan", "source": "clear-private-plan", "target": "deliver-private-plan"}, {"id": "sync-systeme-social-name-systeme-service-retry", "source": "sync-systeme-social-name", "target": "systeme-service-retry", "sourceHandle": "error"}, {"id": "systeme-wealth-plan-tag-systeme-service-retry", "source": "systeme-wealth-plan-tag", "target": "systeme-service-retry", "sourceHandle": "error"}, {"id": "verify-systeme-contact-systeme-service-retry", "source": "verify-systeme-contact", "target": "systeme-service-retry", "sourceHandle": "error"}]'::jsonb,version=version+1,published_at=now(),updated_at=now() where id=reply.id;
-- Keep the new branches readable in the flow editor.
update zernflow.flows f set nodes=(select jsonb_agg(case
 when f.id=original.id and n->>'id'='msg-email' then jsonb_set(n,'{data,label}','"Ask for Wealth Flow email"')
 when f.id=original.id and n->>'id'='clear-other-offer' then jsonb_set(n,'{position}','{"x":120,"y":390}')
 when f.id=original.id and n->>'id'='wealth-plan-pending' then jsonb_set(n,'{position}','{"x":120,"y":570}')
 when f.id=plan.id and n->>'id'='msg-private-plan' then jsonb_set(n,'{position}','{"x":120,"y":210}')
 when f.id=plan.id and n->>'id'='clear-other-offer' then jsonb_set(n,'{position}','{"x":120,"y":390}')
 when f.id=plan.id and n->>'id'='mark-private-plan' then jsonb_set(n,'{position}','{"x":120,"y":570}')
 when f.id=reply.id and n->>'id'='offer-reply-router' then jsonb_set(n,'{position}','{"x":800,"y":30}')
 when f.id=reply.id and n->>'id'='offer-delivery-router' then jsonb_set(n,'{position}','{"x":420,"y":1050}')
 when f.id=reply.id and n->>'id'='register-private-plan' then jsonb_set(n,'{position}','{"x":800,"y":1150}')
 when f.id=reply.id and n->>'id'='clear-private-plan' then jsonb_set(n,'{position}','{"x":800,"y":1350}')
 when f.id=reply.id and n->>'id'='deliver-private-plan' then jsonb_set(n,'{position}','{"x":800,"y":1550}')
 else n end order by ord) from jsonb_array_elements(f.nodes) with ordinality a(n,ord)) where f.id in(original.id,plan.id,reply.id);
insert into zernflow.flow_versions(flow_id,version,nodes,edges,viewport,name)
select id,version,nodes,edges,viewport,name from zernflow.flows f where id in(original.id,plan.id,reply.id)
and not exists(select 1 from zernflow.flow_versions v where v.flow_id=f.id and v.version=f.version);
end;
$offers$;
commit;
